const body = $json.body && typeof $json.body === 'object' ? $json.body : ($json || {});
const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
const expectedRuntimeKey = String($env.MERCHROUTE_RUNTIME_KEY || '').trim();
const suppliedRuntimeKey = String(headers['x-merchroute-runtime-key'] || headers['X-MerchRoute-Runtime-Key'] || '').trim();
if (!expectedRuntimeKey || suppliedRuntimeKey !== expectedRuntimeKey) return [{ json: { valid: false, ok: false, httpStatus: 401, message: 'OZON intake runtime 认证失败' } }];
const uuid = (value) => /^[0-9a-f-]{36}$/i.test(String(value || ''));
const jobId = String(body.jobId || body.id || '').trim();
const taskId = String(body.taskId || jobId).trim();
const sku = String(body.sku || '').trim();
const productJsonPath = String(body.productJsonPath || '').trim();
const revision = Number(body.revision || 0);
const signature = String(body.signature || '').trim();
const storeId = String(body.storeId || '').trim();
const storeAlias = String(body.storeAlias || '').trim().toLowerCase();
const publicationId = String(body.publicationId || '').trim();
const credentialVersionId = String(body.credentialVersionId || '').trim();
const credentialBindingMode = String(body.credentialBindingMode || (credentialVersionId ? 'VAULT' : storeId ? 'LEGACY_PUBLICATION' : 'PURE_LEGACY')).trim().toUpperCase();
const storeConfigVersion = Number(body.storeConfigVersion || 0);
const warehouseId = String(body.warehouseId || '').trim();
const rowVersion = Number(body.rowVersion || 0);
const leaseOwner = String(body.leaseOwner || '').trim();
const leaseToken = String(body.leaseToken || '').trim();
const offerContractHash = String(body.offerContractHash || '').trim();
const materializationHash = String(body.materializationHash || '').trim();
const storeScoped = Boolean(storeId || storeAlias || publicationId || credentialVersionId);
if (!uuid(jobId) || !taskId || !/^[A-Za-z0-9._-]{1,100}$/.test(sku) || !productJsonPath) return [{ json: { valid: false, ok: false, httpStatus: 400, message: 'jobId/taskId、sku、productJsonPath 无效' } }];
if (!Number.isInteger(revision) || revision < 1) return [{ json: { valid: false, ok: false, httpStatus: 400, message: 'revision 必须是正整数' } }];
if (signature && !/^sha256:[a-f0-9]{64}$/i.test(signature)) return [{ json: { valid: false, ok: false, httpStatus: 400, message: 'signature 格式无效' } }];
if (storeScoped) {
  if (!uuid(storeId) || !/^[a-z0-9][a-z0-9-]{1,31}$/.test(storeAlias) || !uuid(publicationId)) return [{ json: { valid: false, ok: false, httpStatus: 400, message: '店铺/publication 快照无效' } }];
  if (!['VAULT','LEGACY_PUBLICATION'].includes(credentialBindingMode)) return [{ json: { valid: false, ok: false, httpStatus: 400, message: '店铺任务 credentialBindingMode 无效' } }];
  if (credentialBindingMode === 'VAULT' && !uuid(credentialVersionId)) return [{ json: { valid: false, ok: false, httpStatus: 400, message: 'VAULT 任务缺少 credentialVersionId' } }];
  if (credentialBindingMode === 'VAULT' && taskId !== storeAlias + '__' + sku + '__r' + revision) return [{ json: { valid: false, ok: false, httpStatus: 400, message: 'VAULT taskId 必须是 <alias>__<sku>__rN' } }];
  if (credentialBindingMode === 'LEGACY_PUBLICATION' && !(storeId === '00000000-0000-4000-8000-000000000002' && storeAlias === 'default' && !credentialVersionId)) return [{ json: { valid: false, ok: false, httpStatus: 400, message: '仅 default 店铺允许 LEGACY_PUBLICATION' } }];
  if (!Number.isInteger(storeConfigVersion) || storeConfigVersion < 1 || !warehouseId || !Number.isInteger(rowVersion) || rowVersion < 1 || !leaseOwner || !leaseToken) return [{ json: { valid: false, ok: false, httpStatus: 400, message: '店铺任务缺少 config/warehouse/rowVersion/lease 快照' } }];
  if (!/^(?:sha256:)?[a-f0-9]{64}$/i.test(offerContractHash) || !/^(?:sha256:)?[a-f0-9]{64}$/i.test(materializationHash)) return [{ json: { valid: false, ok: false, httpStatus: 400, message: 'Offer/materialization 合同哈希无效' } }];
}
return [{ json: {
  valid: true,
  jobId,
  taskId,
  sku,
  productJsonPath,
  revision,
  signature,
  storeId,
  storeAlias,
  publicationId,
  credentialVersionId,
  credentialBindingMode,
  storeConfigVersion,
  warehouseId,
  rowVersion,
  leaseOwner,
  leaseToken,
  offerContractHash,
  materializationHash
} }];
